using System;using System.IO;using System.Text;using System.Linq;using System.Security.Cryptography;using System.Collections.Generic;
namespace Frociart {
    // Each template owns one validated directory. Archiving/restoring is a single directory rename.
    internal sealed class FlowTemplateStore {
        internal const int MaxEntries=32,MaxArchive=32,MaxTotalBytes=8388608,MaxDraftCharacters=524288;
        internal sealed class Entry {
            internal readonly string Id,Raw,Draft,Fingerprint,Problem;internal readonly FlowCodeTemplate Definition;internal readonly bool Archived;
            internal Entry(string id,string raw,string draft,string fingerprint,FlowCodeTemplate definition,string problem,bool archived){Id=id;Raw=raw;Draft=draft;Fingerprint=fingerprint;Definition=definition;Problem=problem;Archived=archived;}
            internal string Name {get{return Definition==null?Problem!=null?"Modello da recuperare":Raw==null?"Bozza di modello":"Modello da recuperare":Definition.Name;}}
        }
        private readonly string root,archive;private static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
        internal FlowTemplateStore(string root){this.root=Path.GetFullPath(root);archive=Path.Combine(this.root,"archive");}
        internal static string NewId(){return Guid.NewGuid().ToString("N");}
        private string Folder(string id,bool archived=false){if(id==null||!System.Text.RegularExpressions.Regex.IsMatch(id,"\\A[a-f0-9]{32}\\z"))throw new ArgumentException("Identificativo del modello non valido.");return Path.Combine(archived?archive:root,id);}
        private static string Fingerprint(byte[] data){using(var hash=SHA256.Create())return String.Concat(hash.ComputeHash(data).Select(b=>b.ToString("x2")));}
        private static bool EmptyFolder(string path){return !Directory.EnumerateFileSystemEntries(path).Any();}
        private static void PlainFolder(string path){if(Directory.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("La cartella del modello non è una cartella locale normale.");}
        private static byte[] Bytes(string path,int limit){using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int count;while((count=input.Read(buffer,0,buffer.Length))>0){if(output.Length+count>limit)throw new IOException("Il file del modello supera il limite di dimensione.");output.Write(buffer,0,count);}return output.ToArray();}}
        internal static string ReadImport(string path){try{return FlowCodeTemplate.Decode(Bytes(path,FlowCodeTemplate.MaxBytes));}catch(ArgumentException error){throw new IOException(error.Message);}}
        internal Entry Load(string id,bool archived=false){string folder=Folder(id,archived);PlainFolder(folder);string raw=null,draft=null,fingerprint=null,problem=null;FlowCodeTemplate definition=null;string file=Path.Combine(folder,"definition.frotemplate");
            if(File.Exists(file))try{if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("Il modello contiene un collegamento a un altro file.");byte[] bytes=Bytes(file,FlowCodeTemplate.MaxBytes);fingerprint=Fingerprint(bytes);raw=Utf8.GetString(bytes);definition=FlowCodeTemplate.Parse(raw);}catch(Exception error){if(!(error is IOException)&&!(error is UnauthorizedAccessException)&&!(error is ArgumentException))throw;problem="Modello da recuperare: "+error.Message;}
            file=Path.Combine(folder,"draft.txt");if(File.Exists(file))try{if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("La bozza contiene un collegamento a un altro file.");draft=Utf8.GetString(Bytes(file,FlowCodeTemplate.MaxBytes));if(draft.Length>MaxDraftCharacters)throw new IOException("Bozza troppo lunga.");}catch(Exception error){if(!(error is IOException)&&!(error is UnauthorizedAccessException)&&!(error is ArgumentException))throw;problem=(problem==null?"":problem+"\n")+"Bozza da recuperare: "+error.Message;}
            return new Entry(id,raw,draft,fingerprint,definition,problem,archived);
        }
        internal IList<Entry> Entries(bool archived=false){string parent=archived?archive:root;var result=new List<Entry>();if(!Directory.Exists(parent))return result.AsReadOnly();PlainFolder(parent);foreach(string folder in Directory.GetDirectories(parent)){string id=Path.GetFileName(folder);if(!System.Text.RegularExpressions.Regex.IsMatch(id,"\\A[a-f0-9]{32}\\z"))continue;try{PlainFolder(folder);if(EmptyFolder(folder))continue;result.Add(Load(id,archived));}catch(IOException error){result.Add(new Entry(id,null,null,null,null,error.Message,archived));}}return result.OrderBy(e=>e.Name,StringComparer.OrdinalIgnoreCase).ThenBy(e=>e.Id,StringComparer.Ordinal).ToList().AsReadOnly();}
        private IDisposable Locked(){Directory.CreateDirectory(root);PlainFolder(root);return new FileStream(Path.Combine(root,".lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}
        private void Capacity(string id,int added,string replaced){int count=0;long total=0;foreach(string folder in Directory.GetDirectories(root)){string key=Path.GetFileName(folder);if(!System.Text.RegularExpressions.Regex.IsMatch(key,"\\A[a-f0-9]{32}\\z"))continue;PlainFolder(folder);if(EmptyFolder(folder))continue;count++;foreach(string name in new[]{"definition.frotemplate","draft.txt"}){string file=Path.Combine(folder,name);if(File.Exists(file)&&!String.Equals(file,replaced,StringComparison.OrdinalIgnoreCase))total+=new FileInfo(file).Length;}}if((!Directory.Exists(Folder(id))||EmptyFolder(Folder(id)))&&count>=MaxEntries)throw new IOException("Hai già 32 modelli. Esporta o sposta nel cestino quelli che non usi.");if(total+added>MaxTotalBytes)throw new IOException("L’archivio dei modelli supera 8 MiB. Esporta o sposta nel cestino quelli che non usi.");}
        private static byte[] Encode(string text,bool draft){if(text==null||text.Length>(draft?MaxDraftCharacters:FlowCodeTemplate.MaxDefinitionCharacters))throw new ArgumentException("Testo del modello troppo lungo.");byte[] bytes=Utf8.GetBytes(text);if(bytes.Length>FlowCodeTemplate.MaxBytes)throw new ArgumentException("Il modello supera 1 MiB.");return bytes;}
        private static void Atomic(string path,byte[] bytes){string temporary=Path.Combine(Path.GetDirectoryName(path),".pending-"+Guid.NewGuid().ToString("N"));try{using(var stream=new FileStream(temporary,FileMode.CreateNew,FileAccess.Write,FileShare.None,8192,FileOptions.WriteThrough)){stream.Write(bytes,0,bytes.Length);stream.Flush(true);}if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
        internal Entry Save(string id,string text,string expectedFingerprint){var definition=FlowCodeTemplate.Parse(text);byte[] bytes=Encode(definition.Text,false);using(Locked()){string folder=Folder(id);PlainFolder(folder);Entry current=Load(id);if(File.Exists(Path.Combine(folder,"definition.frotemplate"))&&current.Fingerprint==null)throw new IOException("Il modello salvato non è leggibile. Conserva il file e salva una copia con un altro nome.");if(current.Fingerprint!=expectedFingerprint)throw new IOException("Il modello è cambiato. Riaprilo oppure salva una copia.");foreach(var entry in Entries())if(entry.Id!=id&&entry.Definition!=null&&String.Equals(entry.Definition.Name,definition.Name,StringComparison.OrdinalIgnoreCase))throw new IOException("Esiste già un modello con questo nome. Scegli un nome diverso.");string file=Path.Combine(folder,"definition.frotemplate");Capacity(id,bytes.Length,file);Directory.CreateDirectory(folder);Atomic(file,bytes);return Load(id);}}
        internal void SaveDraft(string id,string text){byte[] bytes=Encode(text,true);using(Locked()){string folder=Folder(id);PlainFolder(folder);string file=Path.Combine(folder,"draft.txt");Capacity(id,bytes.Length,file);Directory.CreateDirectory(folder);Atomic(file,bytes);}}
        internal bool ClearDraft(string id,string expectedText){using(Locked()){string folder=Folder(id);PlainFolder(folder);string file=Path.Combine(folder,"draft.txt");if(!File.Exists(file))return true;string actual=ReadImport(file);if(actual!=expectedText)return false;File.Delete(file);if(!Directory.EnumerateFileSystemEntries(folder).Any())Directory.Delete(folder);return true;}}
        internal void Archive(string id,string expectedFingerprint){using(Locked()){string source=Folder(id);PlainFolder(source);if(!Directory.Exists(source))throw new IOException("Il modello non è più disponibile.");Entry entry=Load(id);if(entry.Fingerprint!=expectedFingerprint)throw new IOException("Il modello è cambiato. Riaprilo prima di spostarlo nel cestino.");CheckKnownFiles(source);Directory.CreateDirectory(archive);PlainFolder(archive);var old=Entries(true);long size=old.Sum(e=>FolderBytes(Folder(e.Id,true)));if(old.Count>=MaxArchive||size+FolderBytes(source)>MaxTotalBytes)throw new IOException("Il cestino dei modelli è pieno. Ripristina o elimina definitivamente alcuni modelli.");Directory.Move(source,Folder(id,true));}}
        internal void Restore(string id){using(Locked()){string source=Folder(id,true),destination=Folder(id);PlainFolder(archive);PlainFolder(source);CheckKnownFiles(source);if(Directory.Exists(destination))throw new IOException("Esiste già un modello con lo stesso identificativo.");Entry entry=Load(id,true);if(entry.Definition!=null&&Entries().Any(e=>e.Definition!=null&&String.Equals(e.Definition.Name,entry.Definition.Name,StringComparison.OrdinalIgnoreCase)))throw new IOException("Esiste già un modello con questo nome. Rinomina quello presente prima di ripristinarlo.");Capacity(id,(int)FolderBytes(source),null);Directory.Move(source,destination);}}
        internal void DeleteArchived(string id){using(Locked()){string folder=Folder(id,true);PlainFolder(archive);PlainFolder(folder);CheckKnownFiles(folder);foreach(string file in Directory.GetFiles(folder))File.Delete(file);Directory.Delete(folder);}}
        private static long FolderBytes(string folder){CheckKnownFiles(folder);long size=Directory.GetFiles(folder).Sum(f=>new FileInfo(f).Length);if(size>MaxTotalBytes)throw new IOException("La cartella del modello supera 8 MiB. Il contenuto è stato conservato.");return size;}
        private static void CheckKnownFiles(string folder){if(!Directory.Exists(folder))throw new IOException("Il modello non è più disponibile.");if(Directory.GetDirectories(folder).Length>0||Directory.GetFiles(folder).Any(f=>Path.GetFileName(f)!="definition.frotemplate"&&Path.GetFileName(f)!="draft.txt"))throw new IOException("La cartella contiene file non riconosciuti: il contenuto è stato conservato.");foreach(string file in Directory.GetFiles(folder))if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new IOException("Il modello contiene un collegamento a un altro file.");}
        internal static void Export(string path,FlowCodeTemplate definition){if(definition==null)throw new ArgumentNullException("definition");Atomic(Path.GetFullPath(path),Encode(definition.ExportText,false));}
    }
}
